package com.akshat.ledgerwise.controller;
import com.akshat.ledgerwise.service.FinanceService; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import java.time.YearMonth; import java.util.Map;
@Controller @RequestMapping("/reports") public class ReportController {private final FinanceService finance;public ReportController(FinanceService f){finance=f;}@GetMapping public String report(@RequestParam(required=false) String month,Model m){String selected=(month==null||month.isBlank())?YearMonth.now().toString():month;Map<String,Object>d=finance.dashboard(selected);m.addAttribute("month",selected);m.addAttribute("income",d.get("income"));m.addAttribute("expense",d.get("expense"));m.addAttribute("balance",d.get("balance"));m.addAttribute("categoryTotals",d.get("categoryTotals"));return "reports";}}